// The Go support code (docs/language-breadth.md, "Go"): one file per package folder, kept by the
// output plan (and written into Run's scratch module), so the generated files of a package share it.
// It implements docs/semantics.md ("Values") as Simulate does, the latent queue, event dispatchers,
// and insertion-ordered sets and maps (Go's maps have no order).
export const GO_RUNTIME_FILE = 'vgraph_runtime.go';

export function goRuntime(packageName: string): string {
  return `// Generated by Blueprint Visual Scripting: support code for the Go generated from graphs in this
// package. Do not edit: it is rewritten when graphs are compiled.

package ${packageName}

import (
	"fmt"
	"math"
	"os"
	"reflect"
	"sort"
	"strconv"
	"strings"
	"time"
)

// ---- Values -----------------------------------------------------------------------------------

// VgFormat is a value as Print shows it.
func VgFormat(value any) string {
	switch v := value.(type) {
	case nil:
		return ""
	case string:
		return v
	case bool:
		if v {
			return "true"
		}
		return "false"
	case int:
		return VgFormatNumber(float64(v))
	case float64:
		return VgFormatNumber(v)
	case fmt.Stringer:
		if rv := reflect.ValueOf(value); rv.Kind() != reflect.Pointer || !rv.IsNil() {
			if _, struct_ := value.(vgFields); !struct_ {
				return v.String()
			}
		}
	}
	return vgJSON(value)
}

// A struct lists its fields, by their names in the graph.
type vgFields interface {
	VgFields() []VgField
}

type VgField struct {
	Name  string
	Value any
}

// Containers print as JSON: sets in ascending order (they have no order of their own), maps in
// the order their keys were added.
func vgJSON(value any) string {
	switch v := value.(type) {
	case nil:
		return "null"
	case string:
		return vgJSONString(v)
	case bool, int:
		return VgFormat(v)
	case float64:
		if math.IsNaN(v) || math.IsInf(v, 0) {
			return "null"
		}
		return VgFormatNumber(v)
	case vgFields:
		parts := []string{}
		for _, field := range v.VgFields() {
			parts = append(parts, vgJSONString(field.Name)+":"+vgJSON(field.Value))
		}
		return "{" + strings.Join(parts, ",") + "}"
	case vgContainer:
		return v.vgJSON()
	case fmt.Stringer:
		return vgJSONString(v.String())
	}
	rv := reflect.ValueOf(value)
	if rv.Kind() == reflect.Pointer && !rv.IsNil() && rv.Elem().Kind() == reflect.Slice {
		rv = rv.Elem()
	}
	if rv.Kind() == reflect.Slice {
		parts := []string{}
		for i := 0; i < rv.Len(); i++ {
			parts = append(parts, vgJSON(rv.Index(i).Interface()))
		}
		return "[" + strings.Join(parts, ",") + "]"
	}
	return vgJSONString(fmt.Sprint(value))
}

func vgJSONString(text string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, c := range text {
		switch c {
		case '"':
			b.WriteString("\\\\\\"")
		case '\\\\':
			b.WriteString("\\\\\\\\")
		case '\\n':
			b.WriteString("\\\\n")
		case '\\r':
			b.WriteString("\\\\r")
		case '\\t':
			b.WriteString("\\\\t")
		case '\\b':
			b.WriteString("\\\\b")
		case '\\f':
			b.WriteString("\\\\f")
		default:
			if c < 0x20 {
				fmt.Fprintf(&b, "\\\\u%04x", c)
			} else {
				b.WriteRune(c)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

// VgFormatNumber writes a number as JavaScript does, so every target language prints numbers the
// same way.
func VgFormatNumber(x float64) string {
	if math.IsNaN(x) {
		return "NaN"
	}
	if math.IsInf(x, 0) {
		if x > 0 {
			return "Infinity"
		}
		return "-Infinity"
	}
	if x == 0 {
		return "0"
	}
	sign := ""
	if x < 0 {
		sign = "-"
	}
	text := strconv.FormatFloat(math.Abs(x), 'e', -1, 64)
	e := strings.IndexByte(text, 'e')
	exponent, _ := strconv.Atoi(text[e+1:])
	digits := strings.Replace(text[:e], ".", "", 1)
	digits = strings.TrimRight(digits, "0")
	if digits == "" {
		digits = "0"
	}
	k, n := len(digits), exponent+1
	switch {
	case k <= n && n <= 21:
		return sign + digits + strings.Repeat("0", n-k)
	case 0 < n && n <= 21:
		return sign + digits[:n] + "." + digits[n:]
	case -6 < n && n <= 0:
		return sign + "0." + strings.Repeat("0", -n) + digits
	}
	rest := ""
	if k > 1 {
		rest = "." + digits[1:]
	}
	expSign := "+"
	if n-1 < 0 {
		expSign = "-"
	}
	return sign + digits[:1] + rest + "e" + expSign + strconv.Itoa(int(math.Abs(float64(n-1))))
}

// VgFloat is the number as a float64 variable, not a constant: Go computes constants exactly, and
// Blueprint's arithmetic is float64's.
func VgFloat(x float64) float64 {
	return x
}

// VgToNumber is a value as a number: text as JavaScript's Number() reads it.
func VgToNumber(value any) float64 {
	switch v := value.(type) {
	case nil:
		return 0
	case bool:
		if v {
			return 1
		}
		return 0
	case int:
		return float64(v)
	case float64:
		return v
	case string:
		text := strings.TrimSpace(v)
		if text == "" {
			return 0
		}
		if number, err := strconv.ParseFloat(text, 64); err == nil && !strings.ContainsAny(text, "_xXpP") {
			return number
		}
	}
	return math.NaN()
}

// VgToBoolean is a value as a boolean.
func VgToBoolean(value any) bool {
	switch v := value.(type) {
	case nil:
		return false
	case bool:
		return v
	case int:
		return v != 0
	case float64:
		return v != 0 && !math.IsNaN(v)
	case string:
		return v != ""
	}
	return true
}

// VgAs is an untyped value as T; nothing (or another type) is T's zero value.
func VgAs[T any](value any) T {
	if typed, ok := value.(T); ok {
		return typed
	}
	var zero T
	switch any(zero).(type) {
	case float64:
		return any(VgToNumber(value)).(T)
	case int:
		return any(int(VgToNumber(value))).(T)
	case bool:
		return any(VgToBoolean(value)).(T)
	case string:
		return any(VgFormat(value)).(T)
	}
	return zero
}

// VgPrint writes a line to standard output.
func VgPrint(text string) {
	fmt.Println(text)
}

// VgFail stops the run (or fails the test) with the message.
func VgFail(message string) {
	panic(vgFailure(message))
}

type vgFailure string

// VgPanicMessage is a recovered panic's message.
func VgPanicMessage(recovered any) string {
	switch v := recovered.(type) {
	case vgFailure:
		return string(v)
	case error:
		return v.Error()
	}
	return fmt.Sprint(recovered)
}

// VgReport ends the program after a panic, with its message, as other languages' runtimes do.
func VgReport(recovered any) {
	os.Stdout.Sync()
	fmt.Fprintln(os.Stderr, "Error:", VgPanicMessage(recovered))
	os.Exit(1)
}

// ---- Containers ------------------------------------------------------------------------------

type vgContainer interface {
	vgJSON() string
}

// VgSet is a set that keeps the order its items were added in.
type VgSet[T comparable] struct {
	items []T
	index map[T]int
}

func NewVgSet[T comparable](items ...T) *VgSet[T] {
	set := &VgSet[T]{index: map[T]int{}}
	for _, item := range items {
		set.Add(item)
	}
	return set
}

func (s *VgSet[T]) Add(item T) {
	if _, ok := s.index[item]; !ok {
		s.index[item] = len(s.items)
		s.items = append(s.items, item)
	}
}

func (s *VgSet[T]) Remove(item T) bool {
	at, ok := s.index[item]
	if !ok {
		return false
	}
	s.items = append(s.items[:at], s.items[at+1:]...)
	delete(s.index, item)
	for i := at; i < len(s.items); i++ {
		s.index[s.items[i]] = i
	}
	return true
}

func (s *VgSet[T]) Contains(item T) bool {
	_, ok := s.index[item]
	return ok
}

func (s *VgSet[T]) Clear() {
	s.items = nil
	s.index = map[T]int{}
}

func (s *VgSet[T]) Len() int {
	return len(s.items)
}

// Sorted is the items in ascending order.
func (s *VgSet[T]) Sorted() *[]T {
	items := append([]T{}, s.items...)
	sort.SliceStable(items, func(i, j int) bool { return vgLess(items[i], items[j]) })
	return &items
}

func (s *VgSet[T]) vgJSON() string {
	return vgJSON(s.Sorted())
}

// VgMap is a map that keeps the order its keys were added in.
type VgMap[K comparable, V any] struct {
	keys   []K
	values map[K]V
}

func NewVgMap[K comparable, V any](items ...any) *VgMap[K, V] {
	m := &VgMap[K, V]{values: map[K]V{}}
	for i := 0; i+1 < len(items); i += 2 {
		m.Put(items[i].(K), items[i+1].(V))
	}
	return m
}

// Empty is a new, empty map of the same types (for code that can't name them).
func (m *VgMap[K, V]) Empty() *VgMap[K, V] {
	return NewVgMap[K, V]()
}

func (m *VgMap[K, V]) Put(key K, value V) {
	if _, ok := m.values[key]; !ok {
		m.keys = append(m.keys, key)
	}
	m.values[key] = value
}

func (m *VgMap[K, V]) Get(key K) (V, bool) {
	value, ok := m.values[key]
	return value, ok
}

func (m *VgMap[K, V]) Remove(key K) bool {
	if _, ok := m.values[key]; !ok {
		return false
	}
	delete(m.values, key)
	for i, k := range m.keys {
		if k == key {
			m.keys = append(m.keys[:i], m.keys[i+1:]...)
			break
		}
	}
	return true
}

func (m *VgMap[K, V]) Clear() {
	m.keys = nil
	m.values = map[K]V{}
}

func (m *VgMap[K, V]) Len() int {
	return len(m.keys)
}

func (m *VgMap[K, V]) Keys() *[]K {
	keys := append([]K{}, m.keys...)
	return &keys
}

func (m *VgMap[K, V]) Values() *[]V {
	values := []V{}
	for _, key := range m.keys {
		values = append(values, m.values[key])
	}
	return &values
}

func (m *VgMap[K, V]) vgJSON() string {
	parts := []string{}
	for _, key := range m.keys {
		name, ok := any(key).(string)
		if !ok {
			name = VgFormat(key)
		}
		parts = append(parts, vgJSONString(name)+":"+vgJSON(m.values[key]))
	}
	return "{" + strings.Join(parts, ",") + "}"
}

func vgLess(a, b any) bool {
	switch x := a.(type) {
	case int:
		return x < b.(int)
	case float64:
		return x < b.(float64)
	case string:
		return x < b.(string)
	case bool:
		return !x && b.(bool)
	}
	return false
}

// ---- Event dispatchers -----------------------------------------------------------------------

// VgDispatcher is Unreal's event dispatcher: handlers are kept with the object and function they
// call, so binding twice adds one and Unbind finds it; they run in the order they were bound.
type VgDispatcher struct {
	handlers []vgHandler
}

type vgHandler struct {
	owner any
	name  string
	run   func(args []any)
}

func (d *VgDispatcher) Bind(owner any, name string, run func(args []any)) {
	for _, h := range d.handlers {
		if h.owner == owner && h.name == name {
			return
		}
	}
	d.handlers = append(d.handlers, vgHandler{owner, name, run})
}

func (d *VgDispatcher) Unbind(owner any, name string) {
	kept := d.handlers[:0]
	for _, h := range d.handlers {
		if h.owner != owner || h.name != name {
			kept = append(kept, h)
		}
	}
	d.handlers = kept
}

func (d *VgDispatcher) Clear() {
	d.handlers = nil
}

// Broadcast runs a copy of the handlers, so events that bind or unbind while running don't disturb
// the loop.
func (d *VgDispatcher) Broadcast(args ...any) {
	for _, h := range append([]vgHandler{}, d.handlers...) {
		h.run(args)
	}
}

// ---- Latent actions --------------------------------------------------------------------------

type vgLatent struct {
	due   float64
	order int
	run   func()
}

var vgLatentQueue []vgLatent
var vgLatentOrder int
var vgLatentStart = time.Now()

func vgLatentClock() float64 {
	return time.Since(vgLatentStart).Seconds()
}

// VgDelay runs then after the given seconds, once the code that started it has returned.
func VgDelay(seconds float64, then func()) {
	vgLatentOrder++
	vgLatentQueue = append(vgLatentQueue, vgLatent{vgLatentClock() + math.Max(0, seconds), vgLatentOrder, then})
}

// VgRunLatentActions runs the latent actions in the order they fall due.
func VgRunLatentActions() {
	for len(vgLatentQueue) > 0 {
		next := 0
		for i, l := range vgLatentQueue {
			if l.due < vgLatentQueue[next].due || (l.due == vgLatentQueue[next].due && l.order < vgLatentQueue[next].order) {
				next = i
			}
		}
		latent := vgLatentQueue[next]
		vgLatentQueue = append(vgLatentQueue[:next], vgLatentQueue[next+1:]...)
		if wait := latent.due - vgLatentClock(); wait > 0 {
			time.Sleep(time.Duration(wait * float64(time.Second)))
		}
		latent.run()
	}
}
`;
}
